type MetaAnnotation = { label: string, citations: SelectedId[], provenance: 'REMOTE_UNVERIFIED', verified: false }
type Result = { canonical: CanonicalOfflineResult, metaAnnotations: MetaAnnotation[] }
function enrich(selectedIds, flags, env, httpStub): Result {
  canonical = runCanonicalOffline(selectedIds) // sole writer of hypotheses, graph, safetyGate, cautionScore
  out = { canonical, metaAnnotations: [] }
  if canonical.state == HUMAN_REVIEW: return out
  if !flags.ENABLED or !flags.CREDITS_CONFIRMED: return out
  if !isAllowedCase(flags.caseId) or !env.apiKeyPresent: return out
  if !atomicReserveCallSlot(limit=1): return out // reserve before dispatch; never reuse a dispatched slot
  attemptedCall = true
  try {
    resp = httpStub.post(FIXED_META_URL, { caseId: flags.caseId, selectedIds: dedup(selectedIds) }, { timeoutMs: 6000, maxBodyBytes: 32768, maxOutputTokens: 256, followRedirects: false })
  } catch TimeoutOrNetwork: record(attempted=true, completed=false, accepted=false); return out
  if resp.status != 200: record(attempted=true, completed=false, accepted=false); return out
  completedResponse = true
  parsed = strictParse(resp.body) // reject extra graph/hypotheses fields, non-object, annotations not array, count > 2
  if parsed == null or parsed.finish_reason != 'stop': record(attempted, completed, accepted=false); return out
  seen = set()
  for a in parsed.annotations:
    if hasControlOrBidi(a.label) or len(a.label) < 3 or len(a.label) > 100 or !allPrintable(a.label): continue_reject_all_and_return(out, attempted, completed, accepted=false)
    cites = dedup(a.citations)
    if len(cites) < 2 or !allIn(cites, selectedIds): continue_reject_all_and_return(out, attempted, completed, accepted=false)
    key = normalize(a.label) + '|' + sort(cites).join(',')
    if key in seen: continue
    seen.add(key); out.metaAnnotations.push({ label: a.label, citations: sort(cites), provenance: 'REMOTE_UNVERIFIED', verified: false })
  record(attempted=true, completed=true, accepted=(out.metaAnnotations.length > 0), countsOnly=true, rawContent=false)
  return out // canonical object is returned by reference/value unchanged; remote path cannot mutate it
}
